WITH with_windows AS (SELECT *, SUM(quantity) OVER w_recent AS cumulative_quantity, AVG(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS quantity_avg_5, LAG(quantity, 1, 0) OVER w_recent_2 AS prev_quantity, LAG(quantity, 2) OVER w_grp AS prev_quantity_2, LEAD(quantity, 1) OVER w_recent_2 AS next_quantity FROM inventory WINDOW w_recent AS (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent_2 AS (PARTITION BY product_id ORDER BY last_restock, id), w_grp AS (PARTITION BY product_id, store_id ORDER BY quantity, id)) SELECT CASE WHEN quantity >= 208 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, CASE WHEN prev_quantity >= 182 THEN 'HIGH' ELSE 'LOW' END AS prev_quantity_tier, PERCENTILE_APPROX(prev_quantity, ARRAY(0.25, 0.5, 0.75)) AS prev_quantity_quartiles, APPROX_PERCENTILE(quantity_avg_5, 0.9) AS quantity_avg_5_p90, MIN(quantity_avg_5) AS min_quantity_avg_5, COUNT(*) AS num_rows, GROUPING(CASE WHEN quantity >= 208 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM with_windows GROUP BY ROLLUP (CASE WHEN quantity >= 208 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN prev_quantity >= 182 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(*) >= 1;
